// R4f-error E4 (transcript-09, WI-4), 4.16336.0 graph (claude-4.16336.0-migrate-20261104 region batch 1): the error-card
// retry decision (c3e34355f G = `JR`; 3.6556.2 cee72b629 f = `iR`) and what it reads — shared-92's transcript row scans
// (3.6556.2 shared-104), c06cf64bb's NON_RESENDABLE sentinel and c73f45bc3's retry nudge copy — generated by
// scripts/extract-retry-decision.mjs into the isolated src/generated/retry-decision-v4 (region plan G6). The 3.6556.2 graph
// (src/generated/retry-decision, tests/retry-decision.test.mjs) stays what the host and session-rail import until the
// production switch. Every outcome is driven by official message shapes (user / assistant / result rows of the session
// transcript); nothing here sends, renders or reads a real session.
import test from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createHash } from 'node:crypto';
import { parsers } from '../../tools/node_modules/prettier/plugins/babel.mjs';
import { setLocale, DEFAULT_LOCALE, t as translate } from '../electron/i18n/index.mjs';
import { extractRetryDecision, retryDecisionReleases, productionRelease, targetRelease } from '../scripts/extract-retry-decision.mjs';
import { decideErrorRetry, rejectedDraftRetryState, lastTurnFailed, unansweredPromptUuid, conversationNotFound, REPEAT_PROMPT_WINDOW_MS }
  from '../src/generated/retry-decision-v4/retry-decision.mjs';
import { lastTerminalRowIndex, pendingPromptUuid, isFailedTerminalRow, isTerminalRow, isHumanPromptRow } from '../src/generated/retry-decision-v4/transcript-rows.mjs';
import { NON_RESENDABLE_REJECTION } from '../src/generated/retry-decision-v4/non-resendable.mjs';
import { retryNudgeMessages, cannedNudges } from '../src/generated/retry-decision-v4/retry-nudge-messages.mjs';
import { NON_RESENDABLE_REJECTION as PRODUCTION_NON_RESENDABLE } from '../src/generated/retry-decision/non-resendable.mjs';

const app = path.resolve(import.meta.dirname, '..');
const generated = path.join(app, 'src/generated/retry-decision-v4');
const productionGenerated = path.join(app, 'src/generated/retry-decision');
const reference = path.resolve(app, '../reference/snapshots/claude-4.16336.0-20261104');
const official = name => fs.readFileSync(path.join(reference, 'ion-dist/assets/v1', name), 'utf8');
const v3 = name => fs.readFileSync(path.resolve(app, '../reference/snapshots/claude-3.6556.2-20261025-192807/ion-dist/assets/v1', name), 'utf8');
const count = (text, needle) => text.split(needle).length - 1;

// Official transcript rows (the SDK message stream a session bucket's `messages` snapshot holds).
const prompt = (uuid, text = 'Fix the failing test') => ({ type: 'user', uuid, message: { role: 'user', content: text } });
const reply = (uuid = 'a1') => ({ type: 'assistant', uuid, message: { role: 'assistant', content: [{ type: 'text', text: 'Working on it' }] } });
const toolResult = uuid => ({ type: 'user', uuid, message: { role: 'user', content: [{ type: 'tool_result', tool_use_id: 'toolu_1', content: 'ok' }] } });
const success = () => ({ type: 'result', subtype: 'success', is_error: false, result: 'Done' });
const failure = (errors = ['Stream closed']) => ({ type: 'result', subtype: 'error_during_execution', is_error: true, errors });
const apiError = () => ({ type: 'assistant', uuid: 'a-err', isApiErrorMessage: true, message: { role: 'assistant', content: [{ type: 'text', text: 'API Error: 529' }] } });
// The decision input c3e34355f Kt (`qR`; 3.6556.2 cee72b629 p) builds from a bucket; fields not named take the store's defaults.
const bucket = fields => ({ error: null, errorKilledTurn: false, errorRejectedPrompt: null, heldInput: [], messages: [], desktopSession: true,
  conversationLost: false, lastPrompt: undefined, ...fields });
const EMPTY = { text: '', isEmpty: true };
const DRAFT = { text: 'one more thing', isEmpty: false };

test('E4 v4 generator: the emitted originals are current, closed over this folder and pinned to the installed sources', async () => {
  const manifest = await extractRetryDecision({ check: true, release: '4.16336.0' });
  assert.equal(manifest.referenceVersion, '4.16336.0');
  assert.equal(manifest.referenceSnapshot, 'snapshots/claude-4.16336.0-20261104');
  for (const module of manifest.modules) assert.equal(module.referenceVersion, '4.16336.0', module.target);
  assert.equal(manifest.adapterModule, null);
  assert.deepEqual(manifest.modules.map(m => m.target), ['define-messages.mjs', 'logger.mjs', 'prompt-text.mjs', 'transcript-rows.mjs', 'non-resendable.mjs',
    'common-messages.mjs', 'retry-nudge-messages.mjs', 'retry-decision.mjs']);
  // Since cds-core wave 5 the graph links cds-core (sharedGraph): the logger's error-mark writers and tags (shared-0 Ac / jc /
  // Pc: pushLoggerErrorMark, truncateLoggerErrorMarks, loggerTags) are cds-core publicNames, imported, never cut again;
  // everything else stays in this folder.
  assert.equal(manifest.sharedGraph, 'cds-core');
  const cds = JSON.parse(fs.readFileSync(path.join(app, 'src/generated/cds-core/manifest.json'), 'utf8'));
  assert.equal(manifest.sharedGraphManifestSha256, createHash('sha256').update(fs.readFileSync(path.join(app, 'src/generated/cds-core/manifest.json'))).digest('hex'));
  const byExport = new Map(Object.entries(cds.publicNames).map(([name, pub]) => [`../cds-core/${pub.target}:${pub.exportName}`, { name, ...pub }]));
  const links = [];
  for (const module of manifest.modules) for (const entry of module.imports) {
    assert.ok(['generated', 'shared-graph'].includes(entry.kind), `${module.target} ${entry.local}`);
    if (entry.kind !== 'shared-graph') continue;
    const pub = byExport.get(`${entry.from}:${entry.name}`);
    assert.ok(pub, `${module.target} ${entry.local} is a cds-core publicName`);
    links.push(`${module.target}:${entry.local}=${pub.name}`);
  }
  // Since cds-core wave 5b the interrupt marker texts (shared-62 pG) and the local-command message cache (shared-92 PJ) are
  // cds-core publicNames too (D1: one copy), imported where this graph used to cut them.
  // Since cds-core wave 8a (R4-K1 addendum A, identity family): the logger's shared-0 Fc (a module-load value cds-core held
  // unpublished) is the publicName identity_shared0_Fc, imported, no longer cut here (was: the five links without
  // 'logger.mjs:Fc=identity_shared0_Fc').
  assert.deepEqual(links.sort(), ['logger.mjs:Ac=pushLoggerErrorMark', 'logger.mjs:Fc=identity_shared0_Fc', 'logger.mjs:Pc=loggerTags', 'logger.mjs:jc=truncateLoggerErrorMarks',
    'prompt-text.mjs:pG=interruptMarkerTexts', 'transcript-rows.mjs:PJ=localCommandMessageCache']);
  for (const [target, local] of [['prompt-text.mjs', 'pG'], ['transcript-rows.mjs', 'PJ'], ['logger.mjs', 'Fc']])
    assert.ok(!manifest.modules.find(m => m.target === target).bindings.some(b => b.name === local), `${target} does not cut ${local}`);
  for (const name of fs.readdirSync(generated).filter(n => n.endsWith('.mjs'))) {
    const text = fs.readFileSync(path.join(generated, name), 'utf8');
    for (const [, from] of text.matchAll(/from "([^"]+)"/g)) assert.ok(from.startsWith('./') || from.startsWith('../cds-core/'), `${name} imports ${from}`);
  }
  const decision = manifest.modules.find(m => m.target === 'retry-decision.mjs');
  // The "no conversation found" check stays split: Ut over the messages, Ht the string test (exported A).
  assert.equal(decision.source, 'c3e34355f-DeHzeGRt.js');
  assert.deepEqual(decision.bindings.map(b => b.name), ['Bt', 'Vt', 'Ht', 'Ut', 'Wt', 'G', 'Yt']);
  assert.deepEqual(decision.imports.map(i => [i.local, i.original]), [['dt', '$w'], ['F', 'Gq'], ['I', 'Wq'], ['be', 'qq']]);
  assert.ok(fs.existsSync(path.join(app, 'scripts/verify-gen-retry-decision.mjs')));
});

test('E4 official: JR, its outcome dispatch, the nudge send and the NON_RESENDABLE record in 4.16336.0', () => {
  const decision = official('c3e34355f-DeHzeGRt.js');
  for (const text of ['G as E,', 'Yt as M,', 'Ht as A,', '"no conversation found with session id"', 'Wt=6e5',
    'return r&&!e.errorKilledTurn||e===void 0||!Bt(e.messages)?"focus":t.isEmpty?"nudge":"nudgeBesideDraft"'])
    assert.equal(count(decision, text), 1, text);
  assert.equal(count(decision, 'nudgeBesideDraft'), 2);
  const session = official('cc43287c9-dzfX-J5i.js');
  assert.equal(count(session, 'JR('), 2);
  for (const text of ['vt=ve?.retryNudge===!0&&J.type==="local"', 'vt||ue(We,_t)',
    'o==="nudge"?(Vs(),Is(I.formatMessage(hL.retryNudge)),i.submit({retryNudge:!0,personSent:a}),!0)',
    'o==="nudgeBesideDraft"&&q?(vC(q,a),i.scheduleFocus(),!0)', 'handleErrorRetry:xC'])
    assert.equal(count(session, text), 1, text);
  assert.equal(count(official('c73f45bc3-C7dtUSq8.js'), 'retryNudge:{defaultMessage:"Try again",id:"hV5oXfyLn2"}'), 1);
  assert.equal(count(official('c06cf64bb-CoZso5N4.js'), '$w=Symbol("NON_RESENDABLE_REJECTION")'), 1);
  assert.equal(count(official('c6b8adeaf-qnfs920E.js'), 'u!==!0&&B.getState().buckets[a.id]?.error===r&&B.getState().recordRejectedPrompt(a.id,Jn,h)'), 1);
});

test('E4 resend / focus: a rejected prompt is resent only while it is still the composer text and resendable', () => {
  const rejected = bucket({ error: 'Message couldn’t be sent', errorRejectedPrompt: 'Fix the failing test' });
  assert.equal(decideErrorRetry(rejected, { text: 'Fix the failing test', isEmpty: false }), 'resend');
  assert.equal(decideErrorRetry(rejected, { text: 'Fix the failing test, please', isEmpty: false }), 'focus');
  assert.equal(decideErrorRetry(rejected, EMPTY), 'focus');
  // A failed send whose text is not the composer's records the sentinel: never resend, even for a matching string.
  const sentinel = bucket({ error: 'Message couldn’t be sent', errorRejectedPrompt: NON_RESENDABLE_REJECTION });
  assert.equal(typeof NON_RESENDABLE_REJECTION, 'symbol');
  assert.equal(NON_RESENDABLE_REJECTION.description, 'NON_RESENDABLE_REJECTION');
  assert.equal(decideErrorRetry(sentinel, { text: 'NON_RESENDABLE_REJECTION', isEmpty: false }), 'focus');
  // The rejected prompt only counts while an error is shown.
  assert.equal(decideErrorRetry(bucket({ errorRejectedPrompt: 'x', messages: [prompt('u1'), failure()], errorKilledTurn: true }), { text: 'x', isEmpty: false }), 'nudgeBesideDraft');
});

test('E4 rejectedDraftRetryState (`oz`): a restored draft from a session that never started resends its own text', () => {
  const state = rejectedDraftRetryState('Start the migration');
  assert.deepEqual(state, { error: '', errorKilledTurn: false, errorRejectedPrompt: 'Start the migration', heldInput: [], messages: [] });
  assert.equal(decideErrorRetry(state, { text: 'Start the migration', isEmpty: false }), 'resend');
  assert.equal(decideErrorRetry(state, { text: 'Something else', isEmpty: false }), 'focus');
  assert.equal(rejectedDraftRetryState(undefined), undefined);
  assert.equal(decideErrorRetry(rejectedDraftRetryState(undefined), EMPTY), 'focus');
});

test('E4 deliver: held input is delivered, beside a draft too (4.16336.0; 3.6556.2 focused beside a draft)', () => {
  const held = bucket({ heldInput: [{ uuid: 'h1', text: 'queued while parked' }], messages: [prompt('u1'), failure()], error: 'Turn failed', errorKilledTurn: true });
  assert.equal(decideErrorRetry(held, EMPTY), 'deliver');
  assert.equal(decideErrorRetry(held, DRAFT), 'deliver');
  assert.equal(count(official('c3e34355f-DeHzeGRt.js'), 'if(e!==void 0&&e.heldInput.length>0)return"deliver"'), 1);
  assert.equal(count(v3('cee72b629-BMo5PDZM.js'), 'if(e!==void 0&&e.heldInput.length>0)return t.isEmpty?"deliver":"focus"'), 1);
  // A rejected prompt still wins over held input.
  assert.equal(decideErrorRetry({ ...held, errorRejectedPrompt: 'x' }, { text: 'x', isEmpty: false }), 'resend');
});

test('E4 repeatPrompt / refillPrompt: a lost CLI conversation sends the last prompt again within 10 minutes, else puts it back', () => {
  const now = 1_800_000_000_000;
  assert.equal(REPEAT_PROMPT_WINDOW_MS, 600_000);
  const lost = sentAt => bucket({ error: 'No conversation found', errorKilledTurn: true, conversationLost: true,
    messages: [prompt('u0', 'Earlier'), reply('a0'), success(), prompt('u1'), failure()], lastPrompt: { uuid: 'u1', text: 'Fix the failing test', sentAt, whole: true } });
  assert.equal(decideErrorRetry(lost(now - 60_000), EMPTY, now), 'repeatPrompt');
  assert.equal(decideErrorRetry(lost(now - REPEAT_PROMPT_WINDOW_MS + 1), EMPTY, now), 'repeatPrompt');
  assert.equal(decideErrorRetry(lost(now - REPEAT_PROMPT_WINDOW_MS), EMPTY, now), 'refillPrompt');
  assert.equal(decideErrorRetry(lost(now - REPEAT_PROMPT_WINDOW_MS - 1), EMPTY, now), 'refillPrompt');
  assert.equal(decideErrorRetry(lost(now), EMPTY, now), 'repeatPrompt');
  assert.equal(decideErrorRetry(lost(now + 5_000), EMPTY, now), 'refillPrompt'); // a clock step backwards never repeats
  assert.equal(decideErrorRetry(lost(undefined), EMPTY, now), 'refillPrompt'); // no sentAt (NaN)
  assert.equal(decideErrorRetry({ ...lost(now - 60_000), lastPrompt: { uuid: 'u1', text: 'Fix', sentAt: now - 60_000, whole: false } }, EMPTY, now), 'refillPrompt');
  assert.equal(decideErrorRetry(lost(now - 60_000), DRAFT, now), 'focus');
  assert.equal(decideErrorRetry({ ...lost(now - 60_000), lastPrompt: undefined }, EMPTY, now), 'focus');
  assert.equal(decideErrorRetry({ ...lost(now - 60_000), lastPrompt: { uuid: 'u0', text: 'Earlier', sentAt: now - 60_000, whole: true } }, EMPTY, now), 'focus');
  // An assistant row after the prompt means the conversation answered: not the prompt to send again.
  const answered = { ...lost(now - 60_000), messages: [prompt('u1'), reply('a1'), failure()] };
  assert.equal(unansweredPromptUuid(answered.messages), undefined);
  assert.equal(decideErrorRetry(answered, EMPTY, now), 'focus');
  // The terminal row's own text also marks the loss (case-insensitive), without the shown category.
  const byText = bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), failure(['No conversation found with session ID 1234'])],
    lastPrompt: { uuid: 'u1', text: 'Fix the failing test', sentAt: now - 1_000, whole: true } });
  assert.equal(conversationNotFound(byText.messages), true);
  assert.equal(decideErrorRetry(byText, EMPTY, now), 'repeatPrompt');
  assert.equal(conversationNotFound([prompt('u1'), { ...success(), result: 'no conversation found with session id 9' }]), true);
  // Only a desktop session: a remote one falls through to the nudge rule.
  assert.equal(decideErrorRetry({ ...byText, desktopSession: false }, EMPTY, now), 'nudge');
});

test('E4 nudge / nudgeBesideDraft: a turn that died after the prompt reached it gets the short Try again, beside a draft', () => {
  const died = bucket({ error: 'Stream closed', errorKilledTurn: true, messages: [prompt('u1'), reply(), failure()] });
  assert.equal(decideErrorRetry(died, EMPTY), 'nudge');
  assert.equal(decideErrorRetry(died, DRAFT), 'nudgeBesideDraft');
  // No terminal row yet: the prompt still waits for its result.
  const midTurn = bucket({ error: 'Process exited', errorKilledTurn: true, messages: [prompt('u1'), reply()] });
  assert.equal(lastTerminalRowIndex(midTurn.messages), null);
  assert.equal(pendingPromptUuid(midTurn.messages), 'u1');
  assert.equal(decideErrorRetry(midTurn, EMPTY), 'nudge');
  // An API-error assistant row is a failed terminal row.
  const api = bucket({ error: 'Overloaded', errorKilledTurn: true, messages: [prompt('u1'), apiError()] });
  assert.equal(isTerminalRow(api.messages[1]), true);
  assert.equal(isFailedTerminalRow(api.messages[1]), true);
  assert.equal(decideErrorRetry(api, EMPTY), 'nudge');
  // A prompt after the last success is unanswered.
  assert.equal(decideErrorRetry(bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), success(), prompt('u2')] }), EMPTY), 'nudge');
  // Subagent rows (parent_tool_use_id) never count as the session's terminal row.
  const sub = bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), failure(), { ...success(), parent_tool_use_id: 'toolu_9' }] });
  assert.equal(lastTerminalRowIndex(sub.messages), 1);
  assert.equal(decideErrorRetry(sub, EMPTY), 'nudge');
  // No error shown but the last turn failed (the error was cleared): still a nudge.
  assert.equal(decideErrorRetry(bucket({ messages: [prompt('u1'), failure()] }), EMPTY), 'nudge');
});

test('E4 focus: an error that killed no turn, a finished turn, or no session at all only focuses the composer', () => {
  assert.equal(decideErrorRetry(bucket({ error: 'Network error', errorKilledTurn: false, messages: [prompt('u1'), failure()] }), EMPTY), 'focus');
  assert.equal(decideErrorRetry(bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), reply(), success()] }), EMPTY), 'focus');
  assert.equal(decideErrorRetry(bucket({ error: 'x', errorKilledTurn: true, messages: [] }), EMPTY), 'focus');
  assert.equal(decideErrorRetry(undefined, EMPTY), 'focus');
  assert.equal(decideErrorRetry(undefined, DRAFT), 'focus');
  // Rows that are not human prompts after a success leave the turn finished: tool results, client echoes, meta rows,
  // synthetic rows and the /model command transcript.
  for (const row of [toolResult('u2'), prompt('client-123'), { ...prompt('u3'), isMeta: true }, { ...prompt('u4'), isSynthetic: true },
    prompt('u5', '<command-name>/model</command-name><command-args>opus</command-args>')]) {
    assert.equal(isHumanPromptRow(row), false, JSON.stringify(row));
    assert.equal(lastTurnFailed([prompt('u1'), success(), row]), false, JSON.stringify(row));
    assert.equal(decideErrorRetry(bucket({ error: 'x', errorKilledTurn: true, messages: [prompt('u1'), success(), row] }), EMPTY), 'focus');
  }
  assert.equal(isHumanPromptRow(prompt('u1')), true);
  assert.equal(isHumanPromptRow({ type: 'user', uuid: 'u1', message: { content: [{ type: 'text', text: 'Hello' }] } }), true);
});

test('E4 retry nudge copy: Try again (hV5oXfyLn2) and the canned continue texts, formatted through the host catalog', () => {
  assert.deepEqual(retryNudgeMessages.retryNudge, { defaultMessage: 'Try again', id: 'hV5oXfyLn2' });
  assert.equal(retryNudgeMessages.afterUsageLimit.id, 'UqWMzb4bJb');
  assert.equal(retryNudgeMessages.afterSleep.id, '4g6ivTtQ3C');
  const intl = { formatMessage: message => translate(message.defaultMessage) };
  // 4.16336.0 Zv (3.6556.2 u_): the formatted retryNudge, the shared common tryAgain (c90d7fd86 t, FazwRldA7z), the two continue texts,
  // then the three English originals.
  assert.deepEqual(cannedNudges(intl).slice(4), ['Try again',
    'I hit my usage limit while you were working, but it has reset now. Please continue from where you left off.',
    'My computer went to sleep while you were working. Please continue from where you left off.']);
  setLocale('zh-CN');
  try {
    const canned = cannedNudges(intl);
    assert.equal(canned.length, 7);
    assert.equal(canned[0], '重试'); // zh-CN/common.mjs 'Try again'
    assert.equal(canned[1], '重试'); // the common tryAgain, same English key
    assert.equal(canned[4], 'Try again'); // the English originals stay in the list
  } finally {
    setLocale(DEFAULT_LOCALE);
  }
});

// Region plan G6: the 4.16336.0 output is an isolated graph beside the 3.6556.2 one that session-rail (3.6556.2) links by
// original identity; neither imports the other and nothing in the app imports the new graph before the production switch.
test('E4 v4 isolated graph: the 3.6556.2 production graph is untouched, still linked by session-rail, and the new one is not wired', async () => {
  assert.equal(productionRelease, '3.6556.2');
  assert.equal(targetRelease, '4.16336.0');
  assert.deepEqual(Object.keys(retryDecisionReleases).sort(), ['3.6556.2', '4.16336.0']);
  assert.equal(retryDecisionReleases['4.16336.0'].output, 'src/generated/retry-decision-v4');
  assert.equal(retryDecisionReleases['3.6556.2'].output, 'src/generated/retry-decision');
  const production = await extractRetryDecision({ check: true });
  assert.equal(production.referenceVersion, '3.6556.2');
  for (const module of production.modules) assert.equal(module.referenceVersion, '3.6556.2', module.target);
  assert.equal(production.isolatedGraph, undefined);
  const manifest = JSON.parse(fs.readFileSync(path.join(generated, 'manifest.json'), 'utf8'));
  assert.deepEqual(Object.keys(manifest.isolatedGraph).sort(), ['heldBy', 'productionGraph', 'productionSwitchNotBeforeBatch']);
  assert.equal(manifest.isolatedGraph.productionGraph, 'src/generated/retry-decision');
  // The reason it is isolated still holds: session-rail's sleep band imports the 3.6556.2 c73f45bc3 l_ from the old folder.
  const rail = JSON.parse(fs.readFileSync(path.join(app, 'src/generated/session-rail/manifest.json'), 'utf8'));
  const link = rail.modules.flatMap(m => m.imports.map(i => ({ ...i, target: m.target }))).filter(i => i.kind === 'retry-decision');
  assert.deepEqual(link.map(i => [i.target, i.from, i.name, i.original]),
    [['sleep-band.mjs', '../retry-decision/retry-nudge-messages.mjs', 'retryNudgeMessages', 'c73f45bc3-B7hbL7H9.js:l_']]);
  // No source file outside the two generated folders imports the 4.16336.0 graph, and the graphs never import each other.
  const walk = dir => fs.readdirSync(dir, { withFileTypes: true }).flatMap(e => e.isDirectory() ? walk(path.join(dir, e.name)) : [path.join(dir, e.name)]);
  const importers = walk(path.join(app, 'src')).filter(f => /\.(m?js|jsx)$/.test(f) && !f.startsWith(generated + path.sep))
    .filter(f => /retry-decision-v4\//.test(fs.readFileSync(f, 'utf8')));
  // round3 integrate-gates (derivation of round3/legacy-prep.json "linker-whitelists"): later 4.16336.0 regions that share a
  // binding this graph holds link it under D1 (session-rail-v4 cf74bc599). A generated linker is allowed only as a
  // 4.16336.0 graph that declares retry-decision-v4 in linkedAreas and names it only through manifest imports of kind
  // 'linked'; no host file, and no 3.6556.2 graph, imports it.
  const GENERATED = path.join(app, 'src/generated');
  const linkedNames = m => { const la = m?.linkedAreas; return !la ? [] : Array.isArray(la) ? la.map(e => typeof e === 'string' ? e : e.area) : Object.keys(la); };
  const graphLinkers = new Map();
  for (const f of importers.filter(f => f.startsWith(GENERATED + path.sep))) {
    const area = path.relative(GENERATED, f).split(path.sep)[0];
    graphLinkers.set(area, [...(graphLinkers.get(area) ?? []), path.basename(f)]);
  }
  assert.deepEqual(importers.filter(f => !f.startsWith(GENERATED + path.sep)), [], 'no host file imports retry-decision-v4');
  for (const [area, files] of graphLinkers) {
    const m = JSON.parse(fs.readFileSync(path.join(GENERATED, area, 'manifest.json'), 'utf8'));
    assert.equal(m.referenceVersion, '4.16336.0', `${area} is a 4.16336.0 graph`);
    assert.ok(linkedNames(m).includes('retry-decision-v4'), `${area} declares retry-decision-v4 in linkedAreas`);
    const targets = new Set();
    for (const mod of m.modules) for (const i of mod.imports ?? [])
      if (/^\.\.\/retry-decision-v4\//.test(i.from ?? '')) { assert.equal(i.kind, 'linked', `${area}/${mod.target} -> ${i.from}`); targets.add(mod.target); }
    for (const name of files) assert.ok(targets.has(name), `${area}/${name} names retry-decision-v4 only through a manifest 'linked' import`);
  }
  for (const name of fs.readdirSync(productionGenerated).filter(n => n.endsWith('.mjs')))
    assert.doesNotMatch(fs.readFileSync(path.join(productionGenerated, name), 'utf8'), /retry-decision-v4/, name);
  // Each graph owns its sentinel: a consumer takes decision and NON_RESENDABLE from the same graph.
  assert.notEqual(NON_RESENDABLE_REJECTION, PRODUCTION_NON_RESENDABLE);
  assert.equal(PRODUCTION_NON_RESENDABLE.description, NON_RESENDABLE_REJECTION.description);
});

// The roots are located on the parsed 4.16336.0 chunk, not by name: Wt is the `6e5` constant the decision G reads, because
// c3e34355f declares two of them; G and Yt carry the export aliases cc43287c9 imports as JR / XR.
test('E4 v4 roots: Wt is the only 6e5 constant among the free variables of G, and G / Yt are the exported E / M', () => {
  const code = official('c3e34355f-DeHzeGRt.js');
  const ast = parsers.babel.parse(code, {});
  const declarations = ast.program.body.flatMap(n => n.type === 'VariableDeclaration' ? n.declarations : []);
  const sixE5 = declarations.filter(d => d.init && code.slice(d.init.start, d.init.end) === '6e5').map(d => d.id.name);
  assert.equal(sixE5.length, 2);
  assert.ok(sixE5.includes('Wt'));
  const g = ast.program.body.find(n => n.type === 'FunctionDeclaration' && n.id.name === 'G');
  const gText = code.slice(g.start, g.end);
  assert.deepEqual(sixE5.filter(name => new RegExp(`[^\\w$]${name.replace('$', '\\$')}[^\\w$]`).test(gText)), ['Wt']);
  const exported = new Map(ast.program.body.filter(n => n.type === 'ExportNamedDeclaration').flatMap(n => n.specifiers.map(s => [s.exported.name, s.local.name])));
  assert.equal(exported.get('E'), 'G');
  assert.equal(exported.get('M'), 'Yt');
  assert.equal(exported.get('A'), 'Ht');
  const session = official('cc43287c9-dzfX-J5i.js');
  assert.equal(count(session, 'from"./c3e34355f-DeHzeGRt.js"'), 1);
  const specifiers = session.match(/import\{([^}]*)\}from"\.\/c3e34355f-DeHzeGRt\.js"/)[1].split(',');
  for (const s of ['D as qR', 'E as JR', 'M as XR', 'N as ZR']) assert.ok(specifiers.includes(s), s);
});

// Fail closed: without `readBy`, Wt's feature matches both 6e5 constants of the chunk and generation stops; a root named
// by a local that no longer carries its features stops it too (check mode, nothing is written).
test('E4 v4 roots fail closed: an ambiguous or re-pointed root stops the 4.16336.0 contract', async () => {
  const spec = retryDecisionReleases['4.16336.0'].modules.find(m => m.target === 'retry-decision.mjs');
  const { readBy } = spec;
  try {
    delete spec.readBy;
    await assert.rejects(extractRetryDecision({ check: true, release: '4.16336.0' }), /retry-decision\.mjs: root Wt features match (Wt, \w+|\w+, Wt)$/);
  } finally {
    spec.readBy = readBy;
  }
  const rows = retryDecisionReleases['4.16336.0'].modules.find(m => m.target === 'transcript-rows.mjs');
  const { features } = rows;
  try {
    rows.features = { ...features, Iq: features.Gq };
    await assert.rejects(extractRetryDecision({ check: true, release: '4.16336.0' }), /transcript-rows\.mjs: root Iq lacks/);
  } finally {
    rows.features = features;
  }
  await extractRetryDecision({ check: true, release: '4.16336.0' });
});
